// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	openQueryPage,
	serverBaseUrl,
	setQueryEditor,
	uniqueRepositoryId
} = require('./workbench-test-helpers.js');

// Milestone M4 of .agent/execplans/workbench-app-shell-and-critique-fixes-20260930.md: results read like a table.
const REPOSITORY_ID = uniqueRepositoryId('workbench-result-scrolling');

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function runQuery(page, query) {
	await setQueryEditor(page, query);
	await page.locator('#exec').click();
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false', { timeout: 15000 });
	await expect(page.locator('#query-results .query-result-status')).toHaveText(/complete/);
	// Let the smooth scroll that brings new results into view finish before measuring or scrolling.
	await page.waitForFunction(() => new Promise(resolve => {
		const start = window.scrollY;
		setTimeout(() => resolve(window.scrollY === start), 250);
	}));
}

test('results scroll with the page under a pinned header', async ({ page }) => {
	await openQueryPage(page, REPOSITORY_ID, { viewport: { width: 1440, height: 900 } });
	await runQuery(page, 'SELECT * WHERE { ?s ?p ?o } LIMIT 400');
	const table = page.locator('#query-results .query-result-table-wrap');
	const tableBox = await table.boundingBox();
	await page.mouse.move(tableBox.x + tableBox.width / 2, Math.min(tableBox.y + 200, 850));
	const before = await page.evaluate(() => window.scrollY);
	// Two wheel events: Firefox scrolls at most about one page per event.
	await page.mouse.wheel(0, 1000);
	await page.mouse.wheel(0, 1000);
	await expect.poll(() => page.evaluate(() => window.scrollY)).toBeGreaterThan(before + 1000);

	const stickyOffset = await page.evaluate(() => parseFloat(getComputedStyle(document.documentElement)
		.getPropertyValue('--workbench-contextbar-height')) || 0);
	const floating = page.locator('#query-results .query-result-floating-head');
	// The sticky wrapper has no height of its own; its viewport shows the copied header row.
	const floatingRow = floating.locator('.query-result-floating-head__viewport');
	await expect(floatingRow).toBeVisible();
	const floatingTop = await floatingRow.evaluate(element => element.getBoundingClientRect().top);
	expect(Math.abs(floatingTop - stickyOffset)).toBeLessThanOrEqual(2);
	await expect(floating).toHaveAttribute('aria-hidden', 'true');

	await expect.poll(() => page.evaluate(() => Array.from(document.querySelectorAll(
		'#query-results tbody tr[data-query-row-index]')).some(row => {
			const box = row.getBoundingClientRect();
			return box.bottom > 0 && box.top < window.innerHeight;
		}))).toBe(true);

	await page.keyboard.press('End');
	await expect(page.locator('#query-results tbody tr[data-query-row-index="399"]')).toBeInViewport();
});

test('full screen fills the screen and scrolls the table', async ({ page }) => {
	await openQueryPage(page, REPOSITORY_ID, { viewport: { width: 1440, height: 900 } });
	await runQuery(page, 'SELECT * WHERE { ?s ?p ?o } LIMIT 400');
	await page.locator('#query-results .query-result-toolbar .query-results__fullscreen').click();
	await expect(page.locator('#query-results')).toHaveAttribute('data-fullscreen', 'true');
	const table = page.locator('#query-results .query-result-table-wrap');
	const height = await table.evaluate(element => element.getBoundingClientRect().height);
	expect(height).toBeGreaterThanOrEqual(900 * 0.8);
	const box = await table.boundingBox();
	await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
	await page.mouse.wheel(0, 1500);
	await expect.poll(() => table.evaluate(element => element.scrollTop)).toBeGreaterThan(500);
	await page.keyboard.press('Escape');
	await expect(page.locator('#query-results')).not.toHaveAttribute('data-fullscreen', 'true');
});

test('mobile records are not capped by an inline height', async ({ page }) => {
	await openQueryPage(page, REPOSITORY_ID, { viewport: { width: 390, height: 844 } });
	await runQuery(page, 'SELECT * WHERE { ?s ?p ?o } LIMIT 25');
	await expect(page.locator('#query-results .query-result-layout')).toHaveAttribute('data-effective-layout', 'records');
	const capped = await page.locator('#query-results [style*="max-height"]').count();
	expect(capped).toBe(0);
});
